<template>
  <section class="workspace-view">
    <div class="workbench-head"><div><h2>{{ tx.title }}</h2><p>{{ tx.subtitle }}</p></div><div class="trace-select"><label>{{ tx.task }}</label><select :value="selected?.task_id || ''" @change="choose(($event.target as HTMLSelectElement).value)"><option v-for="task in tasks" :key="task.task_id" :value="task.task_id">{{ task.request.task_name }} · {{ task.task_id.slice(-8) }}</option></select><button :disabled="loading" @click="load">↻</button></div></div>
    <template v-if="selected">
      <div class="trace-banner panel"><div><span>{{ tx.traceId }}</span><b class="mono">{{ selected.trace_id }}</b></div><div><span>{{ tx.taskId }}</span><b class="mono">{{ selected.task_id }}</b></div><div><span>{{ tx.status }}</span><b>{{ statusText(locale,selected.status) }}</b></div><div><span>{{ tx.totalTime }}</span><b>{{ totalTime }} ms</b></div><div><span>{{ tx.checkpoint }}</span><b>V{{ selected.version }}</b></div></div>
      <div class="trace-layout">
        <article class="panel trace-panel">
          <div v-for="(step,index) in selected.steps" :key="step.node" class="trace-step">
            <div class="trace-axis"><span class="mono">{{ String(index+1).padStart(2,'0') }}</span><i :class="step.status"></i></div>
            <div class="trace-card">
              <div class="step-head"><div><h3>{{ nodeName(step.node,step.label) }}</h3></div><div><span :class="['step-status',step.status]">{{ stepStatus(step.status) }}</span><b class="mono">{{ step.duration_ms || 0 }} ms</b></div></div>
              <div class="io-grid"><section><h4>{{ tx.output }}</h4><div v-if="Object.keys(step.output_summary||{}).length" class="kv"><div v-for="(value,key) in step.output_summary" :key="key"><span>{{ summaryKey(String(key)) }}</span><b>{{ renderValue(value, String(key)) }}</b></div></div><p v-else>{{ tx.noOutput }}</p></section><section><h4>{{ tx.diagnostic }}</h4><p :class="{error:step.error}">{{ step.error || tx.normal }}</p></section></div>
            </div>
          </div>
        </article>
        <aside class="panel context-panel">
          <section><h3>{{ tx.context }}</h3><dl><div><dt>{{ tx.workshop }}</dt><dd>{{ selected.request.factory_id }} / {{ selected.request.workshop_id }}</dd></div><div><dt>{{ tx.productionDate }}</dt><dd>{{ selected.request.production_date }}</dd></div><div><dt>{{ tx.provider }}</dt><dd>{{ selected.request.llm_provider }}</dd></div><div><dt>{{ tx.source }}</dt><dd>{{ selected.request.data_source==='real'?tx.enterprise:tx.planningDb }}</dd></div></dl></section>
          <section><h3>{{ tx.errors }}</h3><div v-if="selected.errors.length" class="log error" v-for="item in selected.errors" :key="item">{{ item }}</div><div v-else class="log ok">✓ {{ tx.noErrors }}</div></section>
          <section><h3>{{ tx.events }}</h3><div v-if="selected.warnings.length" class="log" v-for="item in selected.warnings" :key="item">{{ item }}</div><div v-else class="log muted">{{ tx.noEvents }}</div></section>
          <section><h3>{{ tx.audit }}</h3><div v-if="selected.reviews.length" class="audit" v-for="record in selected.reviews" :key="record.reviewed_at"><i></i><div><b>{{ record.reviewer }} · {{ reviewAction(record.action) }}</b><small>{{ formatDateTime(locale,record.reviewed_at) }}</small><p v-if="record.comment">{{ record.comment }}</p></div></div><div v-else class="log muted">{{ tx.noAudit }}</div></section>
        </aside>
      </div>
    </template>
    <div v-else-if="!loading" class="panel empty">{{ tx.empty }}</div>
    <p v-if="error" class="error-line">{{ error }}</p>
  </section>
</template>

<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { getTask,listTasks } from '../services/api'
import type { TaskSnapshot } from '../types'
import { formatDateTime,statusText,type Locale } from '../utils/workbench'
const props=defineProps<{locale:Locale;initialTaskId?:string}>()
const tasks=ref<TaskSnapshot[]>([]),selected=ref<TaskSnapshot|null>(null),loading=ref(false),error=ref('')
const copy={
  'zh-TW':{title:'運行追蹤',subtitle:'以任務與 Trace 為單位檢視節點耗時、資料摘要、降級及人工操作。',task:'選擇任務',traceId:'TRACE ID',taskId:'TASK ID',status:'任務狀態',totalTime:'節點總耗時',checkpoint:'快照版本',output:'輸出摘要',diagnostic:'節點診斷',noOutput:'此節點未輸出摘要',normal:'執行正常，未觸發降級。',context:'執行上下文',workshop:'工廠 / 車間',productionDate:'生產日期',provider:'模型供應商',source:'業務資料源',enterprise:'企業整合資料源',planningDb:'計畫資料庫',ruleEngine:'規則引擎',errors:'錯誤與降級',noErrors:'沒有錯誤記錄',events:'下發與系統事件',noEvents:'尚無系統事件',audit:'人工操作稽核',noAudit:'尚無人工審核記錄',empty:'尚無可追蹤任務',completed:'完成',degraded:'降級',running:'執行中',approve:'核准',modify:'修改核准',reject:'退回',summaryTotal:'設備總數',summaryAvailable:'可用設備',summarySource:'資料來源',summaryShiftCount:'班次數量',summaryHeadcount:'當班人數',summaryOrderCount:'工單數量',summaryAssignmentCount:'分配數量',summaryFallbackResources:'備援資源',summaryPlanId:'計畫編號',summaryRiskCount:'風險數量',summaryGeneratedBy:'產生方式',summaryFallback:'降級狀態',summaryReviewRequired:'需要審核',summaryCheckpoint:'狀態快照',yes:'是',no:'否',durable:'已持久化'},
  'zh-CN':{title:'运行追踪',subtitle:'以任务和 Trace 为单位查看节点耗时、数据摘要、降级及人工操作。',task:'选择任务',traceId:'TRACE ID',taskId:'TASK ID',status:'任务状态',totalTime:'节点总耗时',checkpoint:'快照版本',output:'输出摘要',diagnostic:'节点诊断',noOutput:'该节点未输出摘要',normal:'执行正常，未触发降级。',context:'执行上下文',workshop:'工厂 / 车间',productionDate:'生产日期',provider:'模型供应商',source:'业务数据源',enterprise:'企业集成数据源',planningDb:'计划数据库',ruleEngine:'规则引擎',errors:'错误与降级',noErrors:'没有错误记录',events:'下发与系统事件',noEvents:'暂无系统事件',audit:'人工操作审计',noAudit:'暂无人工审核记录',empty:'暂无可追踪任务',completed:'完成',degraded:'降级',running:'执行中',approve:'批准',modify:'修改批准',reject:'退回',summaryTotal:'设备总数',summaryAvailable:'可用设备',summarySource:'数据来源',summaryShiftCount:'班次数量',summaryHeadcount:'当班人数',summaryOrderCount:'工单数量',summaryAssignmentCount:'分配数量',summaryFallbackResources:'备用资源',summaryPlanId:'计划编号',summaryRiskCount:'风险数量',summaryGeneratedBy:'生成方式',summaryFallback:'降级状态',summaryReviewRequired:'需要审核',summaryCheckpoint:'状态快照',yes:'是',no:'否',durable:'已持久化'},
  'en-US':{title:'Run trace',subtitle:'Inspect node latency, data summaries, fallbacks and human actions by task and trace.',task:'Select task',traceId:'TRACE ID',taskId:'TASK ID',status:'Task status',totalTime:'Node time',checkpoint:'Snapshot version',output:'Output summary',diagnostic:'Node diagnostics',noOutput:'This node produced no summary',normal:'Execution completed without fallback.',context:'Execution context',workshop:'Factory / workshop',productionDate:'Production date',provider:'Model provider',source:'Business data source',enterprise:'Enterprise data source',planningDb:'Planning database',ruleEngine:'Rules engine',errors:'Errors and fallbacks',noErrors:'No errors recorded',events:'Release and system events',noEvents:'No system events yet',audit:'Human audit trail',noAudit:'No human review recorded',empty:'No traceable tasks',completed:'Completed',degraded:'Fallback',running:'Running',approve:'Approved',modify:'Modified & approved',reject:'Returned',summaryTotal:'Equipment total',summaryAvailable:'Available',summarySource:'Data source',summaryShiftCount:'Shifts',summaryHeadcount:'Headcount',summaryOrderCount:'Orders',summaryAssignmentCount:'Assignments',summaryFallbackResources:'Fallback resources',summaryPlanId:'Plan ID',summaryRiskCount:'Risks',summaryGeneratedBy:'Generated by',summaryFallback:'Fallback',summaryReviewRequired:'Review required',summaryCheckpoint:'Checkpoint',yes:'Yes',no:'No',durable:'Durable'},
}
const tx=computed(()=>copy[props.locale]),totalTime=computed(()=>selected.value?.steps.reduce((sum,s)=>sum+(s.duration_ms||0),0)||0)
const nodeNames:Record<string,[string,string,string]>={device_resource:['設備資源檢索','设备资源检索','Equipment retrieval'],shift_query:['班組排班查詢','班组排班查询','Shift roster query'],station_assign:['工位任務分配','工位任务分配','Station allocation'],plan_generate:['作業方案產生','作业方案生成','Plan generation'],human_review:['人工審核','人工审核','Human review']}
function nodeName(node:string,fallback:string){const index=props.locale==='zh-TW'?0:props.locale==='zh-CN'?1:2;return nodeNames[node]?.[index]||fallback}
function stepStatus(value:string){return value==='degraded'?tx.value.degraded:value==='completed'?tx.value.completed:tx.value.running}
function reviewAction(value:string){return value==='approve'?tx.value.approve:value==='modify'?tx.value.modify:tx.value.reject}
const summaryKeys:Record<string,string>={total:'summaryTotal',available:'summaryAvailable',source:'summarySource',shift_count:'summaryShiftCount',headcount:'summaryHeadcount',order_count:'summaryOrderCount',assignment_count:'summaryAssignmentCount',fallback_resources:'summaryFallbackResources',plan_id:'summaryPlanId',risk_count:'summaryRiskCount',generated_by:'summaryGeneratedBy',fallback:'summaryFallback',review_required:'summaryReviewRequired',checkpoint:'summaryCheckpoint'}
function summaryKey(key:string){const label=summaryKeys[key];return label?String((tx.value as any)[label]):key}
function renderValue(value:unknown,key:string){if(key==='source')return value==='real'?tx.value.enterprise:tx.value.planningDb;if(key==='generated_by'&&String(value).includes('deterministic'))return tx.value.ruleEngine;if(key==='checkpoint'&&value==='durable')return tx.value.durable;if(Array.isArray(value))return value.join(', ');if(value&&typeof value==='object')return JSON.stringify(value);if(typeof value==='boolean')return value?tx.value.yes:tx.value.no;return String(value)}
async function choose(taskId:string){if(!taskId)return;loading.value=true;error.value='';try{selected.value=await getTask(taskId)}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function load(){loading.value=true;error.value='';try{tasks.value=await listTasks();await choose(props.initialTaskId&&tasks.value.some(t=>t.task_id===props.initialTaskId)?props.initialTaskId:tasks.value[0]?.task_id||'')}catch(e:any){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>

<style scoped>
.workspace-view{display:grid;gap:16px}.workbench-head{display:flex;justify-content:space-between;align-items:end}.workbench-head h2{font:600 25px "Bahnschrift";margin:0}.workbench-head p{color:var(--muted);font-size:11px;margin:6px 0 0}.trace-select{display:flex;gap:7px;align-items:center}.trace-select label{font-size:9px;color:var(--muted)}.trace-select select,.trace-select button{background:#111a1e;color:var(--paper);border:1px solid var(--steel);padding:9px 10px}.trace-select select{min-width:280px}.trace-banner{display:grid;grid-template-columns:1.2fr 1.4fr .7fr .7fr .6fr;gap:1px;background:var(--steel)}.trace-banner div{background:#111a1e;padding:12px 15px}.trace-banner span,.trace-banner b{display:block}.trace-banner span{font-size:8px;color:var(--muted)}.trace-banner b{font-size:10px;margin-top:5px}.trace-layout{display:grid;grid-template-columns:1fr 330px;gap:16px}.trace-panel,.context-panel{padding:20px;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,0 100%)}.trace-step{display:grid;grid-template-columns:40px 1fr;gap:12px;position:relative}.trace-step:not(:last-child)::before{content:"";position:absolute;left:19px;top:33px;bottom:-4px;width:1px;background:var(--steel)}.trace-axis{z-index:1}.trace-axis span{display:grid;place-items:center;width:38px;height:30px;background:#10191d;border:1px solid var(--steel);color:var(--coolant);font-size:8px}.trace-axis i{display:block;width:5px;height:5px;border-radius:50%;background:var(--ok);margin:8px auto}.trace-axis i.degraded{background:var(--oxide)}.trace-card{padding:0 0 18px}.step-head{display:flex;justify-content:space-between;border-bottom:1px solid var(--steel);padding:3px 0 9px}.step-head h3{font-size:12px;margin:0}.step-head small{font-size:8px;color:#617177}.step-head>div:last-child{display:flex;gap:12px;align-items:center}.step-head>div:last-child b{font-size:9px;color:var(--coolant)}.step-status{font-size:8px;color:var(--ok)}.step-status.degraded{color:var(--oxide)}.io-grid{display:grid;grid-template-columns:1.4fr .6fr;gap:16px;padding-top:10px}.io-grid h4{font-size:8px;color:var(--muted);margin:0 0 7px}.io-grid p{font-size:9px;color:#78878b;margin:0;line-height:1.5}.io-grid p.error{color:#ef896e}.kv{display:flex;gap:6px;flex-wrap:wrap}.kv div{border:1px solid var(--steel);background:#0e171b;padding:5px 7px}.kv span,.kv b{display:block}.kv span{font-size:7px;color:#607177}.kv b{font-size:9px;margin-top:2px}.context-panel section{padding-bottom:16px;margin-bottom:16px;border-bottom:1px solid var(--steel)}.context-panel section:last-child{border:0}.context-panel h3{font-size:10px;color:var(--muted);margin:0 0 10px}dl{margin:0}dl div{display:flex;justify-content:space-between;padding:6px 0;font-size:9px}dt{color:#6c7c80}dd{margin:0}.log{font-size:9px;line-height:1.5;padding:8px;background:#10191d;margin-bottom:5px}.log.ok{color:var(--ok)}.log.error{color:#ef896e}.log.muted{color:#68777b}.audit{display:grid;grid-template-columns:10px 1fr;gap:7px;margin-bottom:10px}.audit i{width:5px;height:5px;border-radius:50%;background:var(--coolant);margin-top:4px}.audit b,.audit small{display:block;font-size:9px}.audit small{font-size:8px;color:#617177;margin-top:3px}.audit p{font-size:9px;margin:5px 0;color:var(--muted)}.empty{padding:80px;text-align:center;color:#68777b;font-size:11px}.error-line{color:#ef896e;font-size:10px}.mono{font-family:"Cascadia Mono",Consolas,monospace}@media(max-width:1050px){.trace-layout{grid-template-columns:1fr}.trace-banner{grid-template-columns:1fr 1fr}.trace-select label{display:none}}@media(max-width:700px){.workbench-head{display:block}.trace-select{margin-top:12px}.trace-select select{min-width:0;flex:1}.io-grid{grid-template-columns:1fr}}
</style>
